import java.util.*;
import java.io.*;

public class D {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long m = in.nextLong();
        System.out.println(solve(n, m));
        in.close();
    }

    static long solve(long n, long m) {
        if (n > m) {
            long temp = n;
            n = m;
            m = temp;
        }
        long total = n * m;
        if (n % 2 == 1 && m % 2 == 1) total--;
        if (n == 1) {
            long base = (n * m) / 6 * 6;
            long rem = (n * m) % 6;
            if (rem == 4) base += 2;
            if (rem == 5) base += 4;
            return base;
        }
        if (n == 2 && m == 2) return 0;
        if (n == 2 && m == 3) return 4;
        if (n == 2 && m == 7) return 12;
        return total;
    }
}
